import base64
import hashlib
import os
import secrets
import urllib.parse
from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


@dataclass
class PKCEAuthResult:
    authorization_url: str
    code_verifier: str
    code_challenge: str
    state: str


@dataclass
class TokenResult:
    access_token: str
    id_token: Optional[str]
    refresh_token: Optional[str]
    token_type: Optional[str]
    expires_in: Optional[int]
    scope: Optional[str]
    raw: Dict[str, Any]


class Auth0PKCEClient:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        audience: Optional[str] = None,
        scope: str = "openid profile email offline_access",
    ) -> None:
        self.domain = domain or os.environ.get("AUTH0_DOMAIN")
        self.client_id = client_id or os.environ.get("AUTH0_CLIENT_ID")
        self.redirect_uri = redirect_uri or os.environ.get("AUTH0_REDIRECT_URI")
        self.audience = audience or os.environ.get("AUTH0_AUDIENCE")
        self.scope = scope

        if not self.domain:
            raise ValueError("AUTH0_DOMAIN is required")
        if not self.client_id:
            raise ValueError("AUTH0_CLIENT_ID is required")
        if not self.redirect_uri:
            raise ValueError("AUTH0_REDIRECT_URI is required")

        self._issuer = f"https://{self.domain}"
        self._authorize_endpoint = f"{self._issuer}/authorize"
        self._token_endpoint = f"{self._issuer}/oauth/token"
        self._userinfo_endpoint = f"{self._issuer}/userinfo"

    @staticmethod
    def _base64url_no_pad(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")

    @staticmethod
    def _generate_code_verifier() -> str:
        return Auth0PKCEClient._base64url_no_pad(secrets.token_bytes(32))

    @classmethod
    def _generate_code_challenge(cls, code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return cls._base64url_no_pad(digest)

    def create_login(self, state: Optional[str] = None) -> PKCEAuthResult:
        code_verifier = self._generate_code_verifier()
        code_challenge = self._generate_code_challenge(code_verifier)
        state = state or self._base64url_no_pad(secrets.token_bytes(16))

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
            "state": state,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.audience:
            params["audience"] = self.audience

        authorization_url = f"{self._authorize_endpoint}?{urllib.parse.urlencode(params)}"
        return PKCEAuthResult(
            authorization_url=authorization_url,
            code_verifier=code_verifier,
            code_challenge=code_challenge,
            state=state,
        )

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> TokenResult:
        data = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "code_verifier": code_verifier,
            "redirect_uri": self.redirect_uri,
        }

        response = requests.post(
            self._token_endpoint,
            json=data,
            headers={"Content-Type": "application/json"},
            timeout=30,
        )
        response.raise_for_status()
        payload = response.json()

        return TokenResult(
            access_token=payload["access_token"],
            id_token=payload.get("id_token"),
            refresh_token=payload.get("refresh_token"),
            token_type=payload.get("token_type"),
            expires_in=payload.get("expires_in"),
            scope=payload.get("scope"),
            raw=payload,
        )

    def get_userinfo(self, access_token: str) -> Dict[str, Any]:
        response = requests.get(
            self._userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def login_with_code(self, code: str, code_verifier: str) -> Dict[str, Any]:
        tokens = self.exchange_code_for_tokens(code, code_verifier)
        userinfo = self.get_userinfo(tokens.access_token)
        return {
            "tokens": tokens,
            "userinfo": userinfo,
        }
